(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*18+Math.sin(x*0.016+t*0.33)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8+Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011-t*0.13)*8+Math.sin((x+y)*0.013+t*0.17)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.7],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+1)*60, 0.1, 2.1, 0.85],
    [400+Math.cos(t*0.45+2)*80, 200+Math.sin(t*0.75+4)*50, 0.07, 1.8, 1.05]
  ];
  let aS=0, iS=0, cS=0, wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
    wS+=Math.sin(d*f*0.4+t*sp*1.2+0.7)*w*0.3;
  }
  const n=src.length;
  const act=aS/n, inh=iS/n, cross=cS/n, warp=wS/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const spiral2=Math.sin(dist*0.02-ang*6+t*0.8)*0.2;
  const fb=Math.sin(act*2.5)*0.15;
  const reaction=Math.tanh((act-inh*0.65+cross*0.4+bg*0.25+spiral+spiral2+fb+warp)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin(sx*0.07-t*0.5)*Math.cos(sy*0.11+t*0.3)*0.3)*1.3)*0.25;
  const grain=Math.sin(sx*0.8+t*5)*Math.sin(sy*0.9-t*4)*0.02;
  const blend=reaction*0.7+cell*0.25+grain, v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,30,80],[15,55,105],[18,90,120],[20,130,130],
    [50,155,115],[120,175,80],[180,190,55],[210,175,65],
    [215,140,70],[200,100,75],[170,65,80],[120,40,75],
    [70,25,65],[30,15,55],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edgePow=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction)*0.08;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgePow+glow*180)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgePow+glow*160)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgePow+glow*120)|0
  ];
}
